INSERT INTO quiz_questions (id, lesson_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES
(gen_random_uuid(), 'reflexes', 'Which of the following is an example of a monosynaptic reflex?', 'Stretch reflex (Knee jerk)', 'Withdrawal reflex', 'Golgi tendon reflex', 'Crossed extensor reflex', 'A', 'The stretch reflex is the only monosynaptic reflex in the human body; all other spinal reflexes are polysynaptic.', 'EASY'),
(gen_random_uuid(), 'pregnancy', 'Which hormone is secreted by cytotrophoblasts and syncytiotrophoblasts to maintain the corpus luteum in early pregnancy?', 'Progesterone', 'hCG', 'Estriol', 'hPL', 'B', 'Human Chorionic Gonadotropin (hCG) rescues the corpus luteum from degradation, maintaining progesterone production until the placenta takes over.', 'EASY'),
(gen_random_uuid(), 'pft', 'In a patient with severe pulmonary fibrosis, pulmonary function testing is expected to show:', 'FEV1/FVC < 70%', 'Increased Total Lung Capacity', 'Decreased FVC with normal/elevated FEV1/FVC ratio', 'Increased Residual Volume', 'C', 'Pulmonary fibrosis is a restrictive lung disease, characterized by reduced lung compliance (low FVC) but preserved airflow rates (normal/high ratio).', 'MEDIUM'),
(gen_random_uuid(), 'ecg', 'On a standard 12-lead ECG, augmented limb leads (aVR, aVL, aVF) compare an active electrode against which reference terminal?', 'Wilson Central Terminal', 'Goldberger Reference Terminal', 'Einthoven Central Terminal', 'Right arm ground lead', 'B', 'Augmented limb leads compare a limb electrode to Goldberger reference terminal, which increases amplitude by 50%. Precordial leads use WCT.', 'MEDIUM'),
(gen_random_uuid(), 'cardiac-cycle', 'Which phase of the cardiac cycle begins immediately after the mitral valve closes?', 'Isovolumetric contraction', 'Isovolumetric relaxation', 'Rapid ventricular ejection', 'Diastasis', 'A', 'Mitral valve closure marks the start of ventricular systole and isovolumetric contraction, generating the first heart sound (S1).', 'EASY'),
(gen_random_uuid(), 'cardiac-output', 'The Fick principle uses which parameter to determine cardiac output?', 'Oxygen consumption and arteriovenous oxygen difference', 'Heart rate and pulse pressure', 'Stroke volume and ejection fraction', 'Aortic pressure and peripheral resistance', 'A', 'Fick principle: CO = Oxygen consumption / (Arterial O2 content - Venous O2 content).', 'MEDIUM'),
(gen_random_uuid(), 'breathing-regulation', 'The primary stimulus for central chemoreceptors to increase ventilation is an increase in:', 'Arterial PO2', 'Arterial hydrogen ion concentration', 'Cerebrospinal fluid PCO2 / H+ concentration', 'Arterial lactic acid', 'C', 'CO2 crosses the blood-brain barrier and hydrates to form H+, which directly stimulates central chemoreceptors in the medulla.', 'MEDIUM'),
(gen_random_uuid(), 'gas-transport', 'Which of the following shifts the oxygen-hemoglobin dissociation curve to the right?', 'Decreased temperature', 'Decreased 2,3-BPG', 'Increased pH (alkalosis)', 'Increased PCO2 (Bohr effect)', 'D', 'Rightward shifts (reduced affinity, facilitating O2 release) are caused by increased temperature, PCO2, 2,3-BPG, and H+ (acidosis).', 'MEDIUM'),
(gen_random_uuid(), 'countercurrent', 'The ascending limb of the loop of Henle is:', 'Impermeable to solutes but highly permeable to water', 'Highly permeable to solutes but impermeable to water', 'Permeable to both water and solutes', 'Impermeable to both water and solutes', 'B', 'The thick ascending limb actively reabsorbs NaCl (via Na-K-2Cl cotransporter) but is impermeable to water, diluting the tubular fluid.', 'MEDIUM'),
(gen_random_uuid(), 'micturition', 'Which nerve mediates contraction of the detrusor muscle during the micturition reflex?', 'Pelvic nerve (parasympathetic)', 'Pudendal nerve (somatic)', 'Hypogastric nerve (sympathetic)', 'Sciatic nerve', 'A', 'Parasympathetic fibers in the pelvic nerve release acetylcholine, stimulating muscarinic receptors (M3) to contract the detrusor muscle.', 'HARD'),
(gen_random_uuid(), 'acid-base', 'Compensation for chronic respiratory acidosis is primarily achieved by the kidneys through:', 'Increased secretion of bicarbonate', 'Increased reabsorption and generation of bicarbonate', 'Decreased secretion of ammonium ions', 'Hyperventilation', 'B', 'In chronic respiratory acidosis, the kidneys compensate by conserving bicarbonate (HCO3-) and secreting hydrogen ions (H+).', 'HARD'),
(gen_random_uuid(), 'gi-motility', 'The electrical pacemaker cells responsible for slow waves in gastrointestinal smooth muscle are:', 'Parietal cells', 'Enterochromaffin-like cells', 'Interstitial cells of Cajal', 'Myenteric plexus neurons', 'C', 'The interstitial cells of Cajal act as the pacemaker cells of the GI tract, generating rhythmic slow-wave electrical activity.', 'MEDIUM'),
(gen_random_uuid(), 'liver-biliary', 'Bile salts are essential for digestion because they act to:', 'Digest proteins into amino acids', 'Emulsify dietary lipids into micelles', 'Buffer gastric acid entering the duodenum', 'Synthesize fat-soluble vitamins', 'B', 'Bile salts act as detergents, emulsifying large lipid droplets into tiny micelles, increasing the surface area for pancreatic lipase.', 'EASY'),
(gen_random_uuid(), 'adrenal-gland', 'Cortisol exerts its metabolic effects primarily by:', 'Stimulating muscle protein synthesis', 'Promoting glucose uptake in adipose tissue', 'Promoting gluconeogenesis and glycogenolysis', 'Stimulating lipogenesis in all tissues', 'C', 'Cortisol is a glucocorticoid that increases blood glucose by stimulating hepatic gluconeogenesis and inhibiting peripheral glucose uptake.', 'MEDIUM'),
(gen_random_uuid(), 'growth-hormone', 'Many of the growth-promoting actions of growth hormone are mediated by:', 'Insulin-like Growth Factor 1 (IGF-1)', 'Thyroid hormone', 'Cortisol', 'Prolactin', 'A', 'Growth hormone stimulates the liver to secrete IGF-1 (somatomedin C), which directly promotes skeletal and cartilage growth.', 'EASY'),
(gen_random_uuid(), 'calcium-bone', 'Parathyroid hormone (PTH) acts to increase plasma calcium levels by:', 'Inhibiting osteoclasts', 'Decreasing calcium reabsorption in the renal distal tubule', 'Stimulating 1,25-dihydroxyvitamin D3 synthesis in the kidneys', 'Increasing phosphate reabsorption in the proximal tubule', 'C', 'PTH stimulates renal 1-alpha-hydroxylase to convert vitamin D to its active form, which increases intestinal calcium absorption.', 'HARD'),
(gen_random_uuid(), 'male-repro', 'Which cell type in the testes is stimulated by FSH to support spermatogenesis and secrete inhibin?', 'Leydig cells', 'Sertoli cells', 'Theca cells', 'Granulosa cells', 'B', 'Sertoli cells are the nurse cells of the testes, stimulated by FSH to support developing sperm cells and secrete inhibin.', 'MEDIUM'),
(gen_random_uuid(), 'lactation', 'The milk-ejection reflex (letdown) is primarily mediated by which hormone?', 'Prolactin', 'Oxytocin', 'Estrogen', 'Progesterone', 'B', 'Oxytocin causes contraction of myoepithelial cells surrounding alveoli in the breast. Prolactin stimulates milk synthesis.', 'EASY'),
(gen_random_uuid(), 'cns-synapse', 'An inhibitory postsynaptic potential (IPSP) is typically generated by the opening of:', 'Ligand-gated sodium channels', 'Ligand-gated calcium channels', 'Ligand-gated chloride or potassium channels', 'Voltage-gated sodium channels', 'C', 'Chloride influx or potassium efflux hyperpolarizes the postsynaptic membrane, moving it further from threshold.', 'MEDIUM'),
(gen_random_uuid(), 'cerebellum', 'The sole output cells of the cerebellar cortex are:', 'Granule cells', 'Purkinje cells', 'Golgi cells', 'Stellate cells', 'B', 'Purkinje cells project inhibitory (GABAergic) outputs to the deep cerebellar nuclei, representing the sole output of the cortex.', 'HARD'),
(gen_random_uuid(), 'eeg-sleep', 'Which EEG waves are characteristic of deep, slow-wave sleep (N3 phase)?', 'Alpha waves (8-13 Hz)', 'Beta waves (14-30 Hz)', 'Theta waves (4-7 Hz)', 'Delta waves (< 4 Hz)', 'D', 'Delta waves are high-amplitude, low-frequency waves characteristic of slow-wave sleep.', 'EASY'),
(gen_random_uuid(), 'pain-pathways', 'Pain and temperature sensations are transmitted to the brain primarily via the:', 'Dorsal column-medial lemniscal pathway', 'Lateral spinothalamic tract', 'Anterior spinothalamic tract', 'Spinocerebellar tract', 'B', 'The lateral spinothalamic tract carries nociceptive (pain) and thermoreceptive (temperature) signals.', 'MEDIUM'),
(gen_random_uuid(), 'ans', 'Postganglionic sympathetic fibers supplying eccrine sweat glands release which neurotransmitter?', 'Norepinephrine', 'Acetylcholine', 'Epinephrine', 'Dopamine', 'B', 'Unlike most sympathetic postganglionic fibers (which release norepinephrine), sweat gland fibers are cholinergic (release acetylcholine).', 'HARD'),
(gen_random_uuid(), 'higher-functions', 'A patient who can understand speech but is unable to produce fluent, grammatical language likely has a lesion in:', 'Wernicke''s area', 'Broca''s area', 'Arcuate fasciculus', 'Primary auditory cortex', 'B', 'A lesion in Broca''s area (inferior frontal gyrus) causes motor/expressive aphasia, characterized by non-fluent speech production.', 'EASY'),
(gen_random_uuid(), 'csf-bbb', 'Cerebrospinal fluid (CSF) is primarily produced by the:', 'Arachnoid villi', 'Choroid plexus', 'Astrocyte end-feet', 'Ependymal cell lining', 'B', 'The choroid plexus, located in the ventricles of the brain, actively secretes CSF.', 'EASY'),
(gen_random_uuid(), 'special-senses-other', 'Sensory transduction of sound in the Organ of Corti is initiated by the influx of which ion?', 'Sodium', 'Calcium', 'Potassium', 'Chloride', 'C', 'Because endolymph is rich in potassium and has a +80mV potential, opening mechanical tip-links triggers a rapid influx of potassium.', 'HARD'),
(gen_random_uuid(), 'special-senses-other', 'A patient presents with conductive hearing loss in the left ear. On examination, tuning fork tests should show:', 'Weber lateralizes to the right, Rinne negative on the left', 'Weber lateralizes to the left, Rinne negative on the left', 'Weber lateralizes to the left, Rinne positive on the left', 'Weber lateralizes to the right, Rinne positive on both sides', 'B', 'Conductive hearing loss lateralizes to the affected (left) ear on Weber test, and yields bone conduction > air conduction (Rinne negative) in that ear.', 'HARD'),
(gen_random_uuid(), 'integrated-exercise', 'During maximal exercise, the increase in skeletal muscle blood flow is driven primarily by:', 'Local metabolic vasodilators (lactic acid, adenosine, K+)', 'Sympathetic activation of beta-2 adrenergic receptors', 'Parasympathetic vasodilation', 'Increased systemic blood pressure alone', 'A', 'Active hyperemia (local metabolic vasodilation) overrides sympathetic vasoconstriction to shunt blood to active skeletal muscles.', 'MEDIUM'),
(gen_random_uuid(), 'nmj', 'Myasthenia gravis is an autoimmune disorder characterized by antibodies directed against:', 'Voltage-gated calcium channels', 'Presynaptic acetylcholine vesicle proteins', 'Postsynaptic nicotinic acetylcholine receptors', 'Acetylcholinesterase', 'C', 'Antibodies bind to and destroy nicotinic ACh receptors at the postsynaptic membrane of the neuromuscular junction.', 'MEDIUM'),
(gen_random_uuid(), 'blood-groups', 'Which of the following blood products is considered the universal donor for plasma transfusions?', 'O negative', 'O positive', 'AB positive', 'AB negative', 'C', 'AB blood contains no antibodies (anti-A or anti-B) in its plasma, making AB plasma compatible with all recipients.', 'MEDIUM');
